    [13310531] = {
        id = 13310531,
        text = "Dear Covenanter:\nDi penghujung musim semi dan awal musim panas ini, kami sudah menyiapkan update terbesar sejak game ini dibuka! \nKali ini kami memperkenalkan beragam gameplay dan konten yang baru, seperti Gerbang Sharam, Perang Wilayah dan Rune Challenge. Selamat bermain! \nTerima kasih atas dukungannya pada tim Hot Games! \nDAL:Kencan tiada akhir! Muuuaaah~\nEngineer bernama “Sima”",
        minipack = 0,
    },
    [13310539] = {
        id = 13310539,
        text = "Dear Covenanter:\nSeorang Idol penuh pesona akan muncul dan bertemu dengan kalian! Di saat yang sama, pengisi suara waifu Mayuri juga muncul~ mau dengar Mayuri bilang apa kan? \nKarena isu jadwal pengisi suara, dubbing tak bisa hadir bersamaan dengan versi game, tapi tim Hot Games akan terus berusaha! \nTim Hot Games akan terus berusaha untuk memberi konten yang makin baik. Meskipun mungkin terlambat, tapi pasti akan tetap ada. \n Tim Produksi Hot Games",
        minipack = 0,
    },
