    },
    [1701547] = {
        id = 1701547,
        text = "Bukannya tidak bagus, tapi kamu harus berniat membawakan hadiah yang lebih kreatif",
        minipack = 0,
    },
    [1701548] = {
        id = 1701548,
        text = "Hmm....? Kelihatan berbeda dari biasanya. Aku akan menerimanya. Tapi jangan salah paham",
