    [1701550] = {
        id = 1701550,
        text = "..... Aku tak akan merasa senang meski dipuji olehmu",
        minipack = 0,
    },
    [1701551] = {
        id = 1701551,
        text = "Aku adalah Wizard terkuat!",
        minipack = 0,
    },
    [1701552] = {
        id = 1701552,
        text = "Saat yang tepat mencoba armor baruku.",
