    },
    [1701557] = {
        id = 1701557,
        text = "Biar kulihat siapa yang berani menghalangiku!",
        minipack = 0,
    },
    [1701558] = {
        id = 1701558,
        text = "Hehe, mau membawaku ke mana?",
        minipack = 0,
    },
    [1701559] = {
        id = 1701559,
        text = "Darling memang paling baik~ Hari ini aku senang sekali.",
        minipack = 0,
    },
    [1701560] = {
        id = 1701560,
        text = "Paling menyayangimu, Darling ~",
        minipack = 0,
    },
    [1701561] = {
        id = 1701561,
        text = "Kalau terburu-buru tidak akan mendapatkan apa-apa, Darling",
