    },
    [1701562] = {
        id = 1701562,
        text = "“Konser” hari ini termasuk sukses.",
        minipack = 0,
    },
    [1701563] = {
        id = 1701563,
        text = "Apa kamu mau kutelepon untuk mengingatkanmu? Darling, jangan sampai terlambat ya.",
        minipack = 0,
    },
    [1701564] = {
        id = 1701564,
        text = "Kenapa? Sudah tidak mau mendengarku bernyanyi? (Tersiksa, menangis)",
