        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "Hari Valentine? Uhm... untukku, yang penting bisa berkencan denganmu adalah hari baik. \nKamu juga merasa senang saat bersamaku, kan?",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "Kekasih tersayang, kuharap kamu mau menerima bunga segar dan surat cintaku. \nKemarilah, habiskan malam yang menyenangkan bersamaku!",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
