        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "Ara, walau ini pertemuan yang ditakdirkan, tapi aku tetap merasa beruntung~ \nAkhirnya penungguan yang panjang selesai.",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "Stupid brother, meski ini hari untuk pasangan kekasih, tapi ada hal yang ingin kukatakan padamu. \nTerima kasih kamu telah menemaniku selama ini.",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "Hari ini aku ingin menggenggam tanganmu lebih lama, berjalan di lapangan penuh dengan bunga-bunga bermekaran atau di bawah pohon yang berwarna-warni. \nHingga matahari terbenam, membentangkan bayangkan kita.",
        minipack = 0,
    },
    [1702067] = {
