    [266326] = {
        id = 266326,
        text = "Lewati 6x stage Spirit Trial",
        minipack = 0,
    },
    [2130514] = {
        id = 2130514,
        text = "1. Battle Natal: \nSelesaikan quest menugaskan Spirit, pada akhirnya akan menerima gift Natal yang diberikan Spirit! Dapatkan Bola Salju, Sephira Natal 2020, CG Ekslusif Natal 2020! \n\n2. Battle Snowman: \nNatal telah tiba, tahun ini mari bermain perang bola salju dengan para Snowman!  Buat tim untuk menyelesaikan tantangan snowman, koleksi material untuk meningkatkan skill pabrik snowman. Bisa mendapatkan banyak Bola Salju dan tukarkan dengan suvenir Natal seperti Avatar Natal, Frame Natal, Token Natal dan item lainnya! \n\n3. Endorse Natal: \nSelama event, Kado seperti \"Rekomendasi Newbie\", \"Penjualan Terbaik\", \"Event Waktu Terbatas\", \"Cultivate Fund\" yang dibeli dengan koin kado dan cara membayar di supply station, dapat diakumulasikan pada progres seluruh server. Saat mencapai jumlah tertentu, klaim hadiah cashback berlimpah~",
        minipack = 0,
    },
    [2130516] = {
        id = 2130516,
        text = "1. Setiap pemain setiap hari 00:00 secara otomatis refresh 3 stage, ketuk ikon stage untuk membuat ruangan. Tidak bisa menantang ulang setelah menyelesaikannya. \n\n2. Dapat menggunakan Diamond untuk langsung refresh stage. Perhatian: Saat refresh, stage yang belum ditantang akan hilang. Peluang refresh harian terbatas. \n\n3. Stage event dapat melalui lobby buat tim membentuk tim, membantu pemain lain dapat mendapatkan hadiah stage yang sama. \n\n4. Peluang assist harian terbatas, jika melewati batas tidak akan dihitung, Harus digunakan pada hari yang sama.",
        minipack = 0,
    },
    [2130518] = {
        id = 2130518,
        text = "Event Battle Snowman telah berakhir, item yang belum Anda klaim di Workshop Snowman, kami kirim via surat kepada Anda, mohon diterima. \nToko tutup setelah 10/1/2020, harap gunakan tepat waktu.",
        minipack = 0,
    },
