    [13310528] = {
        id = 13310528,
        text = "Dear Covenanter:\nTerima kasih atas dukungannya untuk Date A Live dan Hot Games! Ditemani kalian, para Spirit akan menyambut tahun baru pertama bersama. \nKarena Date A Live mendapat dukungan dari semuanya! Tim Hot Games jadi bisa terus berkembang dan bertambah kuat, berusaha untuk kalian! \nDAL:Kencan tiada akhir! \n Tim Produksi Hot Games",
        minipack = 0,
    },
    [13310536] = {
        id = 13310536,
        text = "",
        minipack = 0,
    },
    [13310544] = {
        id = 13310544,
        text = "Dear Covenanter:\nBerkat dukungan kalian, Date A Live~ Spirit Pledge merayakan ulang tahun yang pertama~ Terima kasih atas dukungannya selama ini. \nSelama setahun ini, cinta di Date A Live seperti lagu, seperti hujan, seperti madu. \nSelama setahun ini, battle di Date A Live sangat sengit, tantangan dan serangan tanpa batas. \nSelama setahun ini, kita membangun cinta dari hati, bergandengan tangan menatap kota yang romantis. \nMenatap masa depan, kita berjanji untuk terus bersama dan memberimu lebih banyak kenangan manis. \nDalam rangka 1 tahun, kami memperbarui janji untuk memberimu kehangatan dan kejutan. \n DAL:Kencan tiada akhir~",
        minipack = 0,
    },
