    [15011015] = {
        id = 15011015,
        text = "Links to other websites provided by us may have different statements or service regulations. Please understand that this website does not protect user privacy in those websites.\n",
        minipack = 0,
    },
    [15011014] = {
        id = 15011014,
        text = "In the course of providing our services to you, our system may also collect information through third party SDK, such services will be unavailable if you do not provide information. We share your personal information with partners or third parties as follows. Please refer to the Privacy Policy or related statement of the third party SDK operator for the scope, purpose and use of information collection:\n",
        minipack = 0,
    },
    [15011011] = {
        id = 15011011,
        text = "This \"Heitao Game Registered User Privacy Policy\" (hereinafter referred to as this \"Privacy Policy\") is an integral part of \"Heitao Game License and Service Agreement\" (hereinafter referred to as this \"User Agreement\") and is concluded between the user (hereinafter referred to as \"You\") and Heitao-interactive (Shanghai) Network Technology Co., Ltd. (hereinafter referred to as \"Heitao\" or \"We/Us\"). User shall not use Heitao Game app and its services unless they have read and accepted all the clauses of this \"Privacy Policy\", using the app and the services shall be deemed to indicate that they have read and agreed to sign this \"Privacy Policy\". \nIf you are a juvenile under the age of 18, you shall read the \"Privacy Policy\" with your guardian carefully; Please use the games and services provided by Heitao Interactive after obtaining your guardian's consent to all the clauses of this \"Privacy Policy\". \nHeitao respect the privacy and information of user, and will closely protect your privacy and information. The following explanations are hereby made for you:\n",
        minipack = 0,
    },
    [15011009] = {
        id = 15011009,
        text = "9.1本协议签订地为中华人民共和国上海市浦东新区。\n9.2本协议的订立、履行、解释及争议的解决均应适用中华人民共和国法律并排除其他一切冲突法的适用。\n9.3如双方就本协议内容或其执行发生任何争议，双方应尽量友好协商解决；协商不成时，任何一方均应向本协议签订地有管辖权的人民法院提起诉讼。\n",
        minipack = 0,
    },
    [15011008] = {
        id = 15011008,
        text = "8.1用户同意保障和维护黑桃公司及其他用户的利益，如因用户违反有关法律、法规或本协议项下的任何条款而给黑桃公司造成损害，用户同意承担由此造成的损害赔偿责任，该等责任包括但不限于给黑桃公司造成的任何直接或间接损失。\n8.2如用户违反本协议、黑桃公司发布的其他规则或者国家法律法规规定，则黑桃公司有权作出独立的判断，立即撤销相关许可，终止为用户提供服务并通过各种合法途径追究用户的法律责任。\n",
        minipack = 0,
    },
    [14210123] = {
        id = 14210123,
        text = "Event Latihan Spesial Musim Semi",
        minipack = 0,
    },
    [15011004] = {
        id = 15011004,
        text = "Heitao Interactive takes user privacy seriously, thus we will not disclose, modify or disclose the registration info of user and the non-public content stored in various services of Heitao Interactive, unless we believes such disclosure is necessary and on good faith, including but not limited to the following condition: \n4.1 In accordance with the provisions of relevant laws and regulations, including when inquired by relevant state organs, providing the content of the info posted by user on Heitao Interactive web page and its post time, Internet address or domain name. \n4.2 Maintaining the intellectual property rights and other important rights of Heitao Interactive. \n4.3 Maintaining the privacy security of user and the general public in emergencies.\n",
        minipack = 0,
    },
    [15011003] = {
        id = 15011003,
        text = "3.1用户如果需要使用和享受黑桃游戏，则用户需要按照《网络游戏管理暂行办法》及文化部《网络游戏服务格式化协议必备条款》的要求，登录实名注册系统并进行实名注册。3.2用户充分理解并同意，黑桃会按照国家相关要求将用户的实名注册信息运用于防沉迷系统之中，即黑桃可能会根据用户的实名注册信息判断用户是否年满18周岁，从而决定是否对用户的游戏账号予以防沉迷限制。\n3.3用户充分理解并同意，为更好地向用户提供黑桃游戏服务，黑桃可以将用户的信息提交给其关联公司，且黑桃有权自行或通过第三方对用户信息进行整理、统计、分析及利用。3.4用户充分理解并同意，黑桃或其合作的第三方可以根据用户信息，通过短信、电话、邮件等各种方式向用户提供关于黑桃游戏的活动信息、推广信息等各类信息。\n",
        minipack = 0,
    },
    [15011001] = {
        id = 15011001,
        text = "In this Agreement, unless otherwise specified, the following terms shall have the following meanings: \n1.1 This Agreement: Refers to the text of this Agreement, Game Rules and their revisions. Once officially released, the foregoing shall form an integral part of this Agreement. This agreement also includes the \"Essential Clauses of Format Agreement for Online Games Services\" formulated by the Ministry of Culture in accordance with the \"Interim Measures for Online Games\" (Decree No.49 of the Ministry of Culture). \n1.2 Heitao Interactive: Refers to Shanghai Heitao Interactive Network Technology Co. Ltd. \n1.3 Game Rules: Refers to the User's Code, Player's Regulations, Game Announcements and Notices regarding Heitao Game as issued and amended by Heitao Game Service Provider. \n1.4 Heitao Game: Refers to the name of all the mobile games published by Heitao Interactive (including but not limited to: any adaptation of the mobile games such as Android and iOS version that operate on mobile smart devices), and updates, upgrades, patches, expansions related to such mobile games; Heitao Game can be provided in the form of software, in which case related software and related documents are also included. \n1.5 User: Also known as \"End User\", refers to the natural person who installs and uses Heitao Game and its services by obtaining the Heitao Game License in the legal channels provided by Heitao Interactive. \n1.6 Heitao Game Service: Refers to the various game related online operation services provided to user by Heitao. \n1.7 Game Data: Refers to the various data recorded by the server generated by user in the process of using Heitao Game, including game log, security log and other data.\n",
        minipack = 0,
    },
