    [14210163] = {
        id = 14210163,
        text = "Dear Covenanter:\n Ratatoskr mendeteksi penurunan di mood Origami Tobiichi dan akan segera inversi. Alasannya tidak jelas, keadaan di lapangan sangat kritis. Setelah bersiap, harap pergi mengecek kondisi dan perhatikan keamanan diri sendiri. \nTim Hot Games yang berusaha menggambar Origami dengan cantik",
        minipack = 0,
    },
    [14210161] = {
        id = 14210161,
        text = "Dear Covenanter:\nBerkat ilmu transform Natsumi yang terbaru, AI Chat Tohka “Tohka konyol” resmi ditambah di Ratatoskr untuk menemanimu mengobrol. \nHot Games akan berusaha demi atmosfir game yang baik dan terus mencoba proyek baru. Setelah ini, masih ada Spirit baru yang bisa diajak mengobrol, nantikan ya! \n Tim Produksi Hot Games",
        minipack = 0,
