    [32311] = {
        id = 32311,
        text = "",
        minipack = 0,
    },
    [13311354] = {
        id = 13311354,
        text = "1. Welcome to the Collection Cabin, the exploration hub of the airship. It mainly determines Collection Capacity (max items obtained in Exploration) and Fly Speed (item acquisition speed in Exploration). \n2. [Upgrading] increases the Collection Cabin's base Capacity and Fly Speed bonuses given to the entire Airship. \n3. Garrison Spirits in [Stats] to increase the Airship's tier based on Spirit BP, which boosts the Capacity percentage bonus (each base stats bonus is calculated separately).",
        minipack = 0,
    },
    [13311353] = {
        id = 13311353,
        text = "1. Welcome to the Component Cabin, the speed hub of the airship. It mainly determines Airship Speed (affects attack order). \n2. [Upgrading] increases the Component Cabin's base Battle Speed bonus given to the entire Airship. \n3. Garrison Spirits in [Stats] to increase the Airship's tier based on Spirit BP, therefore increasing the Battle Speed percentage bonus (each base stats bonus is calculated separately). \n4. [Component Assembly] lets you equip Airship Components found in exploration. Modify the Airship with techs from different civilizations to gain more stats and extra drops.",
        minipack = 0,
    },
    [13311352] = {
        id = 13311352,
        text = "1. Welcome to the Armor Cabin, the defensive hub of the airship. It mainly determines the DEF of the Airship. \n2. [Upgrading] increases the Armor Cabin's base DEF bonus given to the entire Airship. \n3. Garrison Spirits in [Stats] to increase the Airship's tier based on Spirit BP, therefore increasing the DEF percentage bonus (each base stats bonus is calculated separately). \n4. Go to [Armor] to enhance armors and increase their defensive stats. Only the \"Shield\" is unlocked at first. You'll have to unlock the other two mystery armors from special \"Knowledge Talents.\" \n5. [Armor Enhance] not only increases armor base stats, it also unlocks EX Skills based on armor level. These are powerful skills with additional special effects!",
        minipack = 0,
    },
    [13311351] = {
        id = 13311351,
        text = "1. Welcome to the Weapon Cabin, the weaponry hub of the airship. It mainly determines the Firepower of the Airship. \n2. [Upgrading] increases the Weapons Cabin's base Firepower bonus given to the entire Airship. \n3. Garrison Spirits in [Stats] to increase the Airship's tier based on Spirit BP, therefore increasing the Firepower percentage bonus (each base stats bonus is calculated separately). \n4. Go to [Weapons] to enhance weapons and increase their offense stats. Only the \"Cannon\" is unlocked at first. You'll have to get the other two mystery weapons from special \"Knowledge Talents.\" \n5. [Weapon Enhance] increases weapon base stats and also unlocks EX Skills based on weapon level. EX Skills are powerful skills with additional special effects and stunning animations!",
        minipack = 0,
    },
    [42094] = {
        id = 42094,
        text = "Gem Energi Lv. A, pakai untuk dapat Gem Lv. A [Miku Izayoi] secara random. (Pakai otomatis setelah diperoleh)",
        minipack = 0,
    },
    [13311350] = {
        id = 13311350,
        text = "1. Welcome to the Command Room, the hub of the airship. It mainly determines Airship HP. \n2. [Upgrade] increases the Command Room's base HP bonus given to the entire Airship. \n3. Garrison Spirits in [Stats] to increase the Airship's tier based on Spirit BP, therefore increasing the HP percentage bonus (each base stats bonus is calculated separately). \n4. In [Airship Quests] you can dispatch qualified Spirits to various Great Civilizations to complete special missions and obtain upgrade materials for the Airship. Complete extra criteria to claim extra rewards!\n5. [Quests] with higher ratings have tougher requirements, but provide better rewards. Quest rating will increase with cabin level. Players can complete up to 8 quests per day, the quota resets at 6:00am on the next day. Quests that still have dispatched Spirits or unclaimed rewards during the reset time will not be replaced with new quests. \n6. In [Form] system, players can consume Form Upgrade Materials to activate different Form Talents divided into two types: individual form bonus talent and all form bonus. The former will only take effect when their corresponding form is active. \n7. Players can switch between the [Form] of the Airship in the flight. Different forms grant different buffs helpful in exploring different types of terrains. (View terrain descriptions in Exploration Maps for details)\n8. [Airship Quests] require Spirits who meets BP requirement to complete. If a Spirit's BP is reduced during a quest and they no longer qualify, you may not be able to claim the quest reward. Please be careful.",
        minipack = 0,
    },
