    [13310533] = {
        id = 13310533,
        text = "Dear Covenanter:\n Setelah diberi makan dan ditempa Hot Games sekian bulan, Shekinah Tohka menjadi lebih kuat. Efek “Pierce” juga ditingkatkan melalui penelitian Ratatoskr. \nJanji Hot Games akhirnya terwujudkan. Date A Live akan menjadi lebih baik dan waifu-mu juga semakin kuat. \nEngineer DAL yang namanya rahasia sepanjang masa",
        minipack = 0,
    },
    [13310532] = {
        id = 13310532,
        text = "Dear Covenanter:\n Di update terbaru, kami mengubah versi “Pierce” dan memperkuat Enhanced Tohka. \nPercayalah, Hot Games akan mewujudkan janji-janji kami. Kami selalu berusaha untuk meningkatkan game sesuai IP Date A Live. Harap selalu memberi feedback yang membangun. \nTim Hot Games yang tak pernah ingkar janji",
